// WP-14: typed access to the mock fixtures. The JSON is generated by scripts/mockfixture (never hand-edit it); the
// casts below are the one place where the generated JSON is declared to match the frozen application types.
import type * as T from "./types";
import configJson from "./fixtures/config.json";
import catalogJson from "./fixtures/catalog.json";
import appJson from "./fixtures/app.json";
import viewSvc from "./fixtures/view_mob.json";
import viewCase from "./fixtures/view_web.json";
import viewDia from "./fixtures/view_data.json";
import viewExp from "./fixtures/view_gro.json";
import viewOps from "./fixtures/view_plat.json";

export interface MockBoard extends T.BoardOption {
  spaceKey: string;
  columns: T.ColumnMapping[];
}

export interface MockCatalog {
  spaces: T.SpaceOption[];
  boards: MockBoard[];
  users: { accountId: string; displayName: string; initials: string }[];
}

export interface MockApp {
  /** Mock clock (ms): every timestamp in the fixtures derives from it. */
  now: number;
  build: T.BuildInfo;
  settings: Record<string, string>;
  connection: T.Connection;
  ui: T.UIState;
  sinkKinds: T.SinkKind[];
  diagnostics: T.Diagnostics;
}

/** Standup configurations, in tab order (ids 1..5). */
export const FIXTURE_CONFIGS = configJson as unknown as T.StandupConfig[];
/** One StandupView per configured standup, in the same order as FIXTURE_CONFIGS. */
export const FIXTURE_VIEWS = [viewSvc, viewCase, viewDia, viewExp, viewOps] as unknown as T.StandupView[];
export const FIXTURE_CATALOG = catalogJson as unknown as MockCatalog;
export const FIXTURE_APP = appJson as unknown as MockApp;
